const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b29Zeichner(S, t, p) {
  const D = B29_DATEN[p.b29];
  if (!D) return;
  if (!S.tex && p.muster && p.muster !== 'uni' && istMuster(p.muster)) S.tex = musterFuellung(S, p.muster);
  // produktSVG setzt dessin = '', sobald im Produktentwickler ein Muster (auch Uni) gewählt ist: dann ersetzt es das Bilddessin
  const musterGewaehlt = p.dessin === '' || (p.muster && p.muster !== p.bildmuster);
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => r[0] === 't' || r[0] === 'm').map((r) => r[1]));
  for (let i = 1; i < n; i++) { const f = p.farben?.[i - 1]; K.push(f === 'gleich' || f == null ? S : materialDefs(f, p.materialien?.[i - 1] ?? 'baumwolle', S.defs)); }
  if (p.glatt) K.forEach((k, i) => { if (i > 0 || !p.muster || p.muster === 'uni') if (k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') k.tex = null; });
  const clip = S.id + 'b29';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  // Musterfeld-Zone bei gewähltem Muster: Bilddessin in Grundfarbe (ohne Naht), Musterfeld einmal über die ganze Form
  const ueber = musterGewaehlt && D.regionen.some((r) => r[0] === 'm') && S.tex;
  // Grundfläche unter allen Flächen schließt Spalten zwischen den vtracer-Flächen
  t.push(`<path d="${D.kontur}" fill="${S.c}" fill-rule="evenodd"/>`);
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (ueber && r[1] === 0) { const c = ton(S, r[0] === 'm' ? 0 : r[2]); t.push(`<path d="${d}" fill="${c}"/>`); }
    else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); }
  }
  if (ueber) t.push(`<path d="${D.kontur}" fill="${S.tex}" fill-rule="evenodd"/>`);
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  // Glanz wie stoff.js flaeche() (Leder, Lack, Satin)
  if (S.glanz) t.push(`<path d="${D.kontur}" fill="url(#${S.id}g)" fill-rule="evenodd"/>`);
  t.push('</g>');
  // Bildmodell hat hier keine Außenkontur gezeichnet: gleiche Stärke wie die übrigen Konturen ergänzen
  if (p.umriss) t.push(`<path d="${D.kontur}" fill="none" stroke="${KONTUR}" stroke-width="0.9" stroke-linejoin="round" fill-rule="evenodd"/>`);
}
